OUT = BASE / 'runtime/chunk3-drafts'
OUT.mkdir(exist_ok=True)
reconciled = (BASE / 'freeze/OT_2002CHUNK3_C_RECONCILED.md').read_text(encoding='utf-8-sig')
stone = (BASE / 'runtime/OT_2002CHUNK3_C_STONE.md').read_text(encoding='utf-8-sig')
all_names = ['Stone-Zsela', 'Stevens', "O'Connor", 'Scalia', 'Kennedy', 'Souter', 'Thomas', 'Ginsburg', 'Breyer']
