def section(text, start, stop):
    pos = text.index(start)
    end = text.find(stop, pos + len(start)) if stop else -1
    return text[pos:end if end >= 0 else len(text)].strip()

def holding(title, rule, authority, explanation, precedent):
    assert len(explanation.split()) <= 350, (title, len(explanation.split()))
    return f'### {title}\n\n**Holding and operative rule:** {rule}\n\n**Authority:** {authority}\n\n**Controlling explanation:** {explanation}\n\n**Precedent treatment:** {precedent}'

cases = []

norton_holdings = '\n\n'.join([
holding('I. Congress may protect the actual interstate services market',
"Congress may prohibit the challenged class of force, threats, physical obstruction and facility destruction intentionally directed at, and directly interfering with, the provision or receipt of reproductive health services in an interstate medical-services market. Local conduct and ideological motive do not remove that class from federal power, and no separate interstate journey by each actor is required.",
'Part I of the opinion of the Court; all nine participating Justices join this rule and explanation.',
"The Court applies American Life League v. Reno, which sustained this direct market-interference mechanism. The service market includes interstate patients, personnel and supplies, and the regulated acts impair access to the services themselves. United States v. Lopez requires an identifiable constitutional connection before aggregate magnitude can matter; the connection here is the conduct's object and operation on that actual market. United States v. Morrison preserved that distinction while rejecting a private-assault remedy resting on more remote economic consequences. The challengers' lack of profit motive does not change the object or operation of the regulated conduct. Congress regulates interference with the market, not the commercial occupation or political beliefs of the person interfering. The two facial questions therefore require no revision of the existing commerce rule.",
'American Life League is applied to the same regulated class; Lopez retains its connection-before-magnitude requirement; Morrison is distinguished by its absence of this direct service-market relationship.'),
holding('II. The service connection regulates defined interference without suppressing advocacy',
"FACE's challenged reproductive-service restrictions survive the facial First Amendment challenge: they require the enacted prohibited means, intentional harm or attempt, and service connection, while preserving protected advocacy and individual attribution. Expressive conduct satisfies intermediate scrutiny because the substantial access-and-safety interest is unrelated to suppressing a message, the burden is no substantially greater than necessary, and usable nonobstructive communication remains.",
'Part II of the opinion of the Court; all nine join. The discussion of the existing civil-threat culpability rule applies its present binding force and does not reopen the earlier proposition-level joins.',
"American Life League supplies the defined-conduct rule and intermediate scrutiny; O'Brien and Ward require fit to the access-and-safety interest. Section 248(a)(1) requires force, threat of force or physical obstruction; intentional injury, intimidation, interference or attempt; and action because a person is or has been obtaining or providing reproductive services, or to intimidate that person, another person or a class from doing so. Interference restricts movement; intimidation concerns reasonable apprehension of bodily harm to oneself or another; obstruction makes ingress or egress impassable or passage unreasonably difficult or hazardous. Section 248(a)(3)'s service branch separately addresses intentional facility-property damage, destruction or attempt because the facility provides services. Those predicates answer the objection that the statute selects a political viewpoint: the service connection identifies the activity whose access is protected, while persuasion, political offense and a listener's voluntary stop are not themselves obstruction. Section 248(d)(1) preserves protected expression; subsection (d)(2) separately creates no new outside-facility speech or religion remedy and preserves existing remedies. A parent or legal guardian is excluded from every FACE penalty and civil remedy insofar as the activity is directed exclusively at that person's own minor; that exclusion supplies no immunity under other law. Claiborne Hardware and American Life League require each defendant's legally attributable violation, rather than shared belief, membership or reduced demand through persuasion. In enforcement, the prosecution must prove liability elements beyond a reasonable doubt; a civil claimant must prove them by a preponderance. Planned Parenthood of the Columbia/Willamette v. American Coalition of Life Activists additionally requires purpose or knowledge of threatening meaning in its reviewed civil-threat category. Context may communicate a threat but cannot eliminate that culpability requirement. Its finding-specific relief supplies no finding or injunction against Norton. The civil holding does not establish a universal criminal-threat mental-state rule.",
"American Life League's conduct, intermediate-scrutiny and attribution holdings remain binding. O'Brien and Ward supply expressive-conduct fit; Claiborne Hardware preserves advocacy and responsibility limits; Planned Parenthood v. ACLA governs only its actual civil-threat and finding-specific remedial scope.")])

cases.append(dict(key='Norton', number=36, case='Norton v. Ashcroft', filename='Norton-v-Ashcroft_merits_2003-01-15.md', date='2003-01-15', citation='Judgment below: 298 F.3d 547; Sixth Circuit No. 00-2487.',
result='Affirmed insofar as the judgment rejects the two granted facial challenges, 9–0; ungranted dispositions undisturbed.',
event="Norton v. Ashcroft. October Term 2002. Merits decision January 15, 2003, on review of the Sixth Circuit's July 31, 2002 judgment affirming dismissal. The questions are whether Congress may regulate local, noncommercial force, threats and obstruction directed at reproductive-health services and whether FACE's service-related distinction violates the First Amendment. The challengers seek facial declaratory and injunctive relief. The warning letter and disputed driveway conversations concern June 2000; no individualized obstruction adjudication is before the Court.",
judgment=f'**Judgment:** Affirmed on the two granted facial claims, 9–0. **Supporting:** {names}. **Opposing:** None. Facial declaratory and injunctive relief on those grounds is denied. The separate as-applied ripeness and ungranted declaratory dispositions remain undisturbed. This judgment is not an endorsement of each direction in the warning letter.',
topology='@@LEAD@@ delivered the opinion of the Court, in which @@LEAD_JOINERS@@ joined. The opinion is unanimous throughout Parts I and II.',
holdings=norton_holdings,
precedent="- American Life League v. Reno (November 13, 1995): applied and reaffirmed on direct market interference, expressive-conduct scrutiny, protected advocacy and individual attribution; its actual definitions and exclusions continue to govern.\n- United States v. Lopez (April 26, 1995): applied; a constitutionally identifiable connection precedes aggregation.\n- United States v. Morrison (May 15, 2000): distinguished; its private-assault rationale does not displace FACE's direct medical-market connection.\n- United States v. O'Brien, 391 U.S. 367, and Ward v. Rock Against Racism, 491 U.S. 781: applied for the fit of expressive-conduct restrictions to an interest unrelated to suppressing a message.\n- NAACP v. Claiborne Hardware Co., 458 U.S. 886: applied; association and lawful persuasion cannot substitute for attributable unlawful conduct.\n- Planned Parenthood of the Columbia/Willamette, Inc. v. American Coalition of Life Activists (December 10, 2002): applied within its civil-threat culpability and finding-specific remedial boundaries; no universal criminal-threat rule is added.",
law="The existing facial commerce and speech rules remain unchanged. FACE's actual conduct, intent, service-connection, expression and own-minor limits govern covered enforcement. Civil threats within Planned Parenthood v. ACLA require purpose or knowledge of threatening meaning. Later enforcement must establish an attributable violation in its own proceeding; this affirmance resolves neither the ungranted warning-letter application nor the disputed encounters.",
separate='', procedure='The facial claims are concluded by the limited affirmance. The distinct lower-court dispositions outside the grant stand. Any later enforcement proceeds under the statute and controlling liability and remedy rules.',
sources='18 U.S.C. §248(a)(1), (a)(3), (c), (d), (e). Norton v. Ashcroft, 298 F.3d 547 (6th Cir. 2002). The disputed driveway encounters have not been adjudicated as violations in this facial proceeding.',
eligible=all_names, full_joiners=all_names, components=[dict(component='Facial commerce challenge',disposition='Affirm',supporting=all_names,opposing=[]),dict(component='Facial expression challenge',disposition='Affirm',supporting=all_names,opposing=[])],
compatibility="Every Associate's N1–N3 joins survives. Stone's approved rule matches the direct-market and defined-conduct holdings, and expressly applies the effective ACLA purpose-or-knowledge standard despite his earlier separate position. Acknowledging that binding rule does not invent Scalia or Thomas's adoption of its original constitutional rationale. Standard criminal/civil proof burdens describe the distinct enforcement proceedings and decide no new offense or remedy. Stone's ungranted-action and remedy limits are preserved; no standing fallback is used.",
fit={'Kennedy':'Authored the operative American Life League rule and can explain its direct-market and expression boundaries without reopening ACLA attribution.', 'O\'Connor':'Can distinguish the binding civil-threat standard from findings needed for enforcement and retain the facial/as-applied boundary.', 'Stone-Zsela':'Approved position coordinates direct market power, advocacy, statutory proof and finding-specific relief; evaluate against available lower-count alternatives.'},
source_map='The frozen neutral packet and its addendum cite the complete Sixth Circuit opinion, corroborated by OpenJurist. They support the meeting, letter, disputed encounters, facial/as-applied separation and lower judgment. The entering-law slice supplies American Life League, Lopez, Morrison and the December 10, 2002 ACLA public rules. The event date and proper merits-review premise are adopted calendar premises. No separate argument or submission date is supplied.'))

newman_holdings = '\n\n'.join([
holding('I. The retained disposition, gift and objection rights are property',
"California's 1997 law gives the properly entitled next of kin a protected property interest in the retained powers to possess and direct disposition of remains, make anatomical gifts and object to corneal removal. The parents adequately plead that they hold those substantive rights; nonmarket character and the label quasi-property do not remove the interest from procedural due process.",
'Part I of the opinion of the Court; all nine Justices join this rule and explanation.',
"Board of Regents v. Roth locates the entitlement in enforceable state law. California retained disposition, gift and refusal powers; former Government Code §27491.47 authorized removal during autopsy only when the coroner lacked knowledge of an objection. That condition recognizes a legally consequential objection, rather than transferring all control to the State. Cleveland Board of Education v. Loudermill separates the entitlement from the procedure for its deprivation. American Manufacturers Mutual Insurance Co. v. Sullivan requires an actual entitlement and preserves an existing one against procedural erasure: these parents allege presently vested control, unlike general eligibility for payment before substantive predicates are met. Phillips v. Washington Legal Foundation confirms that lack of market value does not settle ownership; its takings remedy is not transferred here. The competing view treats retrieval authority as the substantive boundary of a burial duty. It fails to account for the same law's continuing refusal and gift powers. California remains free to define substantive rights, but omission of an effective opportunity to object does not itself extinguish the retained right. Health and Safety Code §7100 preserves contrary decedent directions and the priority of spouse, children, parents, next kin in intestate order and the public administrator if the estate has sufficient assets. The pleaded parents' priority is not defeated by an established superior claimant or donor direction. Autopsy authority and transfer of corneal tissue for another's use are distinct. The reasonable-contact provision for other tissue in §7151.5(a)(2) is not the text of former §27491.47; the later consent amendment does not determine 1997 process.",
'Roth and Loudermill supply the state-created-entitlement/procedure distinction; Sullivan is applied with its actual-entitlement qualification; Phillips supplies the distinction between ownership and commercial value. No immutable constitutional property category for human remains is adopted.'),
holding('II. An established procedure cannot rely categorically on later state remedies',
"Available state postdeprivation remedies do not categorically defeat a §1983 procedural-due-process claim alleging a predictable, irreversible deprivation under established governmental procedures. Adequacy of process must be assessed under the actual circumstances, and exhaustion of state remedies is not a prerequisite to the federal action.",
'Part II of the opinion of the Court; all nine Justices join this rule and explanation.',
"Logan v. Zimmerman Brush Co. distinguishes an established state procedure from the random, unauthorized conduct addressed in Parratt v. Taylor and Hudson v. Palmer, where advance safeguards are impracticable. The complaint alleges a planned removal practice, not an unforeseeable departure from a valid system. The mere availability of a tort action therefore cannot end the federal claim. The former statute's liability shield also prevents assuming an effective compensatory remedy existed. Patsy v. Board of Regents separately rejects exhaustion; that rule does not itself prove that the available process was inadequate. The defendants may establish circumstances justifying action without advance protection, but the complaint cannot be dismissed by presuming such circumstances or treating every later remedy as constitutionally sufficient.",
'Logan is applied to established procedure; Parratt and Hudson retain their genuine random-and-unauthorized-act setting; Patsy preserves the distinct no-exhaustion rule.'),
holding('III. The actual process must be adjudicated under Mathews',
"The reinstated claim must be adjudicated under Mathews by weighing the retained private interest and irreversibility of removal, the risk of mistaken disregard of an entitled person's objection and value of feasible safeguards, and the government's actual retrieval and health burdens. Ordinarily a planned irreversible deprivation requires a practicable opportunity beforehand, but actual urgency or impracticability may justify proceeding without advance process; the pleadings establish neither mandatory advance consent in every case nor adequate eventual money relief.",
f'Part III of the opinion of the Court, joined by the eight Associates: {eight_names}. Stone-Zsela also joins the integrated Mathews framework in Part III, ordinary practicable-opportunity principle with its actual-urgency or impracticability qualification, and factual, responsibility, defense and remedy remit. He withholds assent only from leaving a more definite ordinary-notice requirement and necessity substantiation unstated. Eight full joins control Part III; the expressly identified common propositions have all nine joins, without synthesis of different rationales.',
"Mathews v. Eldridge requires one contextual inquiry, and Gilbert v. Homar illustrates why urgency can affect initial safeguards while continuing to require meaningful protection. Irreversible loss of an objection makes a practicable opportunity valuable; a real medical retrieval window may constrain the form and timing of that opportunity. Neither the value of donation nor the strength of the private interest eliminates the other side of the inquiry. The present record supplies no findings about available contact information, retrieval urgency, conflicting authorization or feasible safeguards. The Court therefore directs assessment under that standard without fixing a more specific ordinary-notice presumption or necessity-proof allocation on these pleadings; it does not decide that eventual compensation suffices. The rule answers the defendants' demand for categorical dismissal while retaining the factual work necessary to decide the actual process. On remand the courts must determine the parents' entitlement under the governing priority and donor rules, the procedure used and practicable safeguards, each defendant's responsibility, preserved defenses, causation, compensable injury and relief under the ordinary governing burdens.",
'Mathews is applied as an integrated process inquiry; Gilbert supplies the distinction between justified urgency and the continuing need for meaningful protection. The judgment makes no broader revision of either rule.')])

newman_separate="Stone-Zsela, concurring in part and concurring in the judgment, joins Parts I and II and Part III's integrated Mathews inquiry, ordinary practicable-opportunity principle with its actual-urgency or impracticability qualification, and factual, responsibility, defense and remedy remit. He would hold that an established procedure irreversibly defeating a retained objection ordinarily requires reasonable efforts at advance notice and a practicable opportunity to object. The parents retain the burden of proving deprivation without adequate process; the State must substantiate an asserted urgency, unavailable contact information or other necessity for bypassing that ordinary safeguard with actual circumstances. Mathews gives substantial value to advance protection of an irreversible choice, while allowing medical timing to constrain its form. Logan and Zinermon distinguish this foreseeable procedure from the random acts in Parratt and Hudson; Patsy separately rejects exhaustion. In his view the missing operational facts determine necessity and liability, and do not prevent stating the ordinary safeguard now. He requires neither a trial-type hearing nor an absolute veto of necessary autopsy, and honors valid donor directions and authorized consent. The lower court should develop contact opportunities, retrieval windows, donor directions, authorization and the decision procedure, then determine the practicable protection withheld and causal responsibility. The parents must prove their entitlement, deprivation, defendant responsibility and compensable injury by a preponderance; applicable immunity and other preserved defenses remain separate. The two retrospective removals establish no entitlement to a prospective decree against the later consent regime. Under Harper his rule would govern the parties and cases still open on direct review; Reynoldsville Casket preserves independent procedural, immunity and remedial limits without selective prospectivity based on reliance alone. Final judgments remain closed, and collateral relief requires its own authorization. The safeguard itself determines neither 1997 immunity nor institutional attribution or damages. His particular ordinary-notice presumption and necessity substantiation are not the Court's additional holding."

cases.append(dict(key='Newman',number=37,case='Newman v. Sathyavaglswaran',filename='Newman-v-Sathyavaglswaran_merits_2003-01-15.md',date='2003-01-15',citation='Judgment below: 287 F.3d 786; Ninth Circuit No. 00-55504.',
result='Judgment reinstating the complaint affirmed, 9–0; eight Justices adopt the contextual process remit and Stone-Zsela states a distinct ordinary-notice rule.',
event="Newman v. Sathyavaglswaran. October Term 2002. Merits decision January 15, 2003. The Court reviews the Ninth Circuit's April 16, 2002 reversal of a Rule 12(b)(6) dismissal. The questions concern the parents' own property interests under California's 1997 corneal-removal scheme and the effect of state postdeprivation remedies when removal follows established governmental procedures. Robert Newman and Barbara Obarski allege removal of their deceased sons' corneas in October 1997 without notice or an attempt to obtain consent, and discovery in September 1999. The coroner and county seek dismissal; the parents seek adjudication of the reinstated retrospective claims.",
judgment=f'**Judgment:** Affirmed, 9–0. **Supporting:** {names}. **Opposing:** None. The Ninth Circuit\'s reversal of the pleading dismissal stands, and the action returns for the process, responsibility, defense and remedy proceedings specified in Part III. Stone-Zsela supports reinstatement on the distinct process rule stated in his concurrence.',
topology='@@LEAD@@ delivered the opinion of the Court, in which @@LEAD_JOINERS@@ joined, and in which Stone-Zsela joined as to Parts I and II and the specified Mathews and remand propositions in Part III. Stone-Zsela filed an opinion concurring in part and concurring in the judgment.\n\n| Writing | Author | Joined by | Relationship to judgment | Scope joined |\n|---|---|---|---|---|\n| Opinion of the Court | @@LEAD@@ | @@LEAD_JOINERS@@; Stone-Zsela as to I-II and the identified III propositions | Affirms reinstatement and governs the return | All eight Associates join I-III; Stone-Zsela also joins the III framework, qualified ordinary-opportunity principle and factual, liability, defense and remedy remit |\n| Concurrence in part and in the judgment | Stone-Zsela | No other Justice | Same reinstatement judgment; distinct ordinary-notice rule | Parts I-II and identified III propositions joined; distinct ordinary-notice and necessity allocation |',
holdings=newman_holdings,
precedent="- Board of Regents v. Roth, 408 U.S. 564: applied; the identified California powers supply the property interest.\n- Cleveland Board of Education v. Loudermill, 470 U.S. 532: applied; a retained substantive entitlement is distinct from its deprivation procedure.\n- American Manufacturers Mutual Insurance Co. v. Sullivan (March 3, 1999): applied and distinguished; an actual vested control interest is alleged here, unlike general eligibility without a service-specific payment entitlement.\n- Phillips v. Washington Legal Foundation (June 15, 1998): applied to ownership despite absence of market value, without importing its takings question.\n- Logan v. Zimmerman Brush Co., 455 U.S. 422: applied to established governmental procedures.\n- Parratt v. Taylor, 451 U.S. 527, and Hudson v. Palmer, 468 U.S. 517: distinguished from the pleaded established removal practice; their genuine impracticability principles remain.\n- Patsy v. Board of Regents, 457 U.S. 496: applied against exhaustion as a prerequisite, separately from adequacy of process.\n- Mathews v. Eldridge, 424 U.S. 319, and Gilbert v. Homar (June 9, 1997): applied to the actual private interest, error risk, feasible safeguards and urgency.",
law="The retained California disposition, gift and objection interests are protected property for eligible holders under the 1997 statutory limits. The established-procedure claim survives a categorical state-remedy defense. Lower courts must apply the contextual Mathews rule stated in Part III to actual urgency, authorization, contact possibilities and safeguards. Those factual and remedial proceedings apply settled law; they are not a reservation of the protected interest. Stone-Zsela's more definite ordinary-notice presumption remains a separate position. The later consent regime is not displaced by adjudication of these retrospective claims.",
separate=newman_separate,procedure='The case returns for further adjudication of the two 1997 removals under the stated entitlement and Mathews rules. The pleading-stage dismissal cannot be reinstated solely because state tort remedies existed. The later consent statute supplies no automatic answer to liability for the earlier removals.',
sources='Newman v. Sathyavaglswaran, 287 F.3d 786 (9th Cir. 2002). Former Cal. Gov. Code §27491.47; Cal. Health & Safety Code §§7100, 7151.5(a)(2). The pleaded claimant status and absence of notice are accepted at this stage; actual urgency, available contacts and authorization require adjudication.',
eligible=associates,full_joiners=associates,components=[dict(component='Reinstatement of complaint',disposition='Affirm',supporting=all_names,opposing=[])],
compatibility="All eight Associates retain P1–P3 without change. Stone joins the entire retained-right and established-procedure holdings but retains his approved ordinary reasonable-notice presumption and substantiation of necessity, stated separately. His conditional Mathews-only fallback is triggered only if missing operational facts prevent even a presumptive safeguard; colleague disagreement is not that condition. Here his authorized rule expressly treats the missing facts as the subjects of necessity and liability proof, so the primary position remains. Stone joins the integrated Mathews framework in Part III, ordinary practicable-opportunity/actual-urgency principle and factual, liability, defense and remedy directions. His partial join withholds assent only from leaving the more definite reasonable-notice presumption and necessity substantiation unstated. The eight full joiners provide direct majority authority for the whole opinion; the specified shared propositions have nine joins. No manufactured expansion join, altered burden for colleagues, or standing fallback is used. His temporal, retrospective-relief, immunity and proof qualifications remain in the concurrence.",
fit={'Breyer':'Gilbert authorship supplies concrete fit for the integrated urgency/process inquiry while preserving the distinct entitlement question.', 'Kennedy':'Sullivan authorship supplies fit for distinguishing an actual retained entitlement from a procedural expectation.', 'Souter':'Can coordinate substantive refusal rights and the actual-process remit without adopting the separate ordinary-notice presumption.'},
source_map='The frozen neutral packet and source addendum rely on the full Ninth Circuit majority and dissent, cross-checked against the reported text. These support the allegations, Rule 12(b)(6) posture, statutory recitations and process reservation. Historical California provisions are supplied through published judicial recitations, not an asserted full historical code examination. The entering-law slice supplies Sullivan, Phillips and Gilbert. The review/date premise is an adopted calendar premise; no separate argument or submission date is supplied.'))

meyer_holdings = '\n\n'.join([
holding('I. Ordinary agency and corporate principles govern compensatory attribution',
"For the compensatory vicarious-liability question presented, the Fair Housing Act incorporates ordinary agency and corporate principles: an employee's qualifying conduct may be attributed to the corporate principal, but office, ownership or control of that corporation alone does not make the individual officer, shareholder or designated broker a second principal. Personal liability requires a legally sufficient individual agency relationship, the individual's own actionable wrongdoing, or an applicable basis for disregarding corporate separateness, with the relevant theory properly preserved and proved.",
'Part I of the opinion of the Court; all nine Justices join this rule and explanation.',
"Nationwide Mutual Insurance Co. v. Darden supplies the interpretive principle that Congress ordinarily incorporates common-law agency where the statute supplies no different rule. The Court uses that method by analogy, not Darden's ERISA employee checklist as an FHA test. General Building Contractors Association v. Pennsylvania distinguishes agency responsibility from an inferred nondelegable duty. United States v. Bestfoods preserves corporate separateness while recognizing supported derivative liability and a genuinely independent direct statutory duty. The FHA's important antidiscrimination purpose cannot alone create an omitted individual principal or impose a nondelegable personal guarantee on every controlling officer. Corporate-employer liability and the actor's own liability remain effective remedies under the actual relationships. Faragher and Ellerth likewise require actual agency-based attribution in their employment settings; their material-aid rules do not make a corporate supervisor the individual employer of all corporate employees. The Holleys must establish the alleged discrimination and a relationship or conduct legally attributing it to each defendant by a preponderance. Here Meyer was president and designated corporate officer/broker, but ownership at the 1996 transaction was disputed after his asserted 1995 transfer. No direct participation was alleged, and the evidence did not establish his direction or approval. Those facts cannot be replaced by a status-based liability rule. Punitive vicarious damages lie outside this reviewed compensatory question.",
'Darden supplies the common-law interpretive analogy; General Building Contractors rejects an unsupported nondelegable duty; Bestfoods preserves corporate distinctions and genuine independent duties; Faragher and Ellerth remain confined to their actual agency-based employment holdings.'),
holding('II. The regulation and broker designation do not impose liability from control alone',
"Former 24 C.F.R. §103.20(b) requires discrimination by the directing or controlling person's employee or agent acting within the scope of that authority; direction or control alone is insufficient. The later notification rule and California's designated-broker supervisory obligations do not themselves displace the ordinary federal attribution requirements.",
'Part II of the opinion of the Court; all nine Justices join this rule and explanation.',
"The complete former regulation qualifies direction or control by an actual employee-or-agent relationship and conduct within its scope. The circuit's approach detaches the control language from those limits. The 1999 provision, §103.202(b), addresses notification of persons who direct or control, while §103.203(a) separately preserves defenses available in court. Notification is not a substantive expansion of responsibility. A state licensing obligation can be relevant to a properly presented agency theory, but the title and right to supervise do not alone establish that the corporate salesman was Meyer's individual agent. The actual relationship must satisfy the applicable ordinary elements. The statutory purpose cannot supply the missing relationship that neither statutory nor regulatory text establishes.",
"The ordinary-agency background described in Darden and General Building Contractors remains governing; Bestfoods's distinction between control of a corporation and the individual's legal responsibility is preserved."),
holding('III. Vacatur removes the special rule while preserving only genuine alternatives',
"The Ninth Circuit's judgment is vacated and the case remanded to determine whether any traditional veil-piercing or other ordinary attribution theory was actually raised and preserved and, if so, whether its elements are established. Rejection of the circuit's special rule neither proves a personal theory nor extinguishes a legally sufficient corporate or employee claim.",
'Part III of the opinion of the Court; all nine Justices join this rule and explanation.',
"The challenged appellate rule governed reversal of a Rule 54(b) summary judgment for Meyer after an earlier pleading disposition of the officer-capacity theory; Triad and Crank claims remained pending. Leaving that broader rule in place would misdirect further proceedings. The opposing request to end all claims against Meyer rests on a contested preservation premise: the United States' argument identifies a claimed prior presentation of veil piercing, while Meyer disputes preservation. The Court resolves neither account by assumption. The return permits only genuinely preserved theories under ordinary procedure. Ownership must be resolved only as material to such a theory; sole ownership, inadequate assets or office alone is no veil-piercing determination. A general rule of personal responsibility for one's own wrongdoing cannot invent a direct-participation allegation or revive an unappealed dismissal. The choice between state and federal veil-piercing law is not reached because the question presented concerns the special FHA attribution rule and preservation of an ordinary theory remains undetermined; Bestfoods likewise left that choice open. The lower courts must apply the governing elements to the evidence and resolve defenses and corresponding relief. Ordinary proceedings may dispose of a preserved theory without trial or new discovery; this remand grants no independent entitlement to either.",
'Bestfoods is applied to the distinction between derivative responsibility and direct wrongdoing, with its choice-of-law reservation preserved. Darden and General Building Contractors supply the ordinary-law remit rather than the rejected special duty.')])

cases.append(dict(key='Meyer',number=39,case='Meyer v. Holley',filename='Meyer-v-Holley_merits_2003-01-22.md',date='2003-01-22',citation='No. 01-1120; 537 U.S. 280. Judgment below: Holley v. Crank, 258 F.3d 1127.',
result='Ninth Circuit judgment vacated and remanded for ordinary attribution and genuinely preserved alternatives, 9–0.',
event="Meyer v. Holley, No. 01-1120, 537 U.S. 280. October Term 2002. Argued December 3, 2002; decided January 22, 2003. The Court reviews the Ninth Circuit's reversal of a Rule 54(b) summary judgment for Meyer on the surviving FHA theory, following an earlier pleading disposition of the officer-capacity theory. Claims against Triad and Crank remained pending. The question is whether corporate ownership, office or designated-broker control alone creates personal vicarious liability for a corporate employee's alleged discriminatory refusal to sell. The Holleys allege a racially discriminatory interference with their attempted 1996 purchase. Meyer's presidency and broker designation are established, but ownership after his asserted 1995 transfer was disputed; direct participation was not alleged. The review concerns compensatory attribution.",
judgment=f'**Judgment:** Vacated and remanded, 9–0. **Supporting:** {names}. **Opposing:** None. The Ninth Circuit\'s special personal vicarious-liability rule is removed. The lower courts must apply ordinary attribution law to genuinely preserved alternatives as directed in Part III. The pending corporate and salesman claims remain distinct.',
topology='@@LEAD@@ delivered the opinion of the Court, in which @@LEAD_JOINERS@@ joined. The opinion is unanimous throughout Parts I–III.',
holdings=meyer_holdings,
precedent="- Nationwide Mutual Insurance Co. v. Darden, 503 U.S. 318 (March 24, 1992): applied by interpretive analogy; its ERISA checklist is not an FHA holding.\n- General Building Contractors Association, Inc. v. Pennsylvania, 458 U.S. 375: applied to reject an inferred nondelegable duty in place of an actual agency relationship.\n- United States v. Bestfoods (June 8, 1998): applied; ordinary ownership does not collapse corporate separateness, and supported derivative liability remains distinct from an independently established direct duty. Its state-or-federal veil-piercing choice remains open in this posture.\n- Faragher v. City of Boca Raton (September 8, 1997) and Burlington Industries, Inc. v. Ellerth (June 26, 1998): their actual-agency and material-aid principles support the attribution distinction without importing their employment-specific applications or reserved defenses as an FHA test.",
law="Ordinary agency and corporate principles govern the presented FHA compensatory attribution. Status and supervisory control alone create no personal nondelegable guarantee. Corporate and direct-actor responsibility remain independent, and properly preserved individual-agency or corporate-disregard theories receive their ordinary elements and defenses. The regulation's relationship-and-scope limits and distinct notification provisions retain their force. This recurring attribution rule is settled; preservation, evidence and relief on the actual surviving theories remain ordinary adjudication.",
separate='',procedure='The vacated appellate judgment returns for further proceedings under ordinary agency and corporate law. The lower courts first identify the properly preserved personal theory, then apply its elements and defenses to the evidence. Existing claims against the corporation and salesman continue in their own posture.',
sources='Meyer v. Holley, No. 01-1120, 537 U.S. 280; Holley v. Crank, 258 F.3d 1127 (9th Cir. 2001). 42 U.S.C. §§3604, 3613; former 24 C.F.R. §103.20(b); 24 C.F.R. §§103.202(b), 103.203(a). Brief for the United States as Amicus Curiae, No. 01-1120 (September 2002), pt. II & n.6. Ownership at the alleged transaction and preservation of ordinary alternatives remain disputed; no direct-participation allegation is established.',
eligible=all_names,full_joiners=all_names,components=[dict(component='Special personal vicarious-liability judgment',disposition='Vacate and remand',supporting=all_names,opposing=[])],
compatibility="Each Associate retains M1–M3. Stone's preserved-direct-participation language is expressly conditional: the validated record contains no such allegation, so the opinion neither creates one nor revives an unappealed ruling. His ordinary-agency/corporate-disregard remit fits the genuinely preserved-theory condition. The corrected summary-judgment posture and disputed ownership do not change his categorical attribution judgment, which forbids title alone doing the work of an actual relationship. No new claim, evidence entitlement or factual preservation finding is supplied. All nine can join the entire opinion; no standing fallback is used.",
fit={'Thomas':'Bestfoods authorship supplies concrete fit for corporate separateness, true direct wrongdoing and derivative alternatives.', 'Souter':'Darden authorship supplies concrete fit for common-law statutory interpretation and relationship-specific attribution.', 'Breyer':'Can integrate the distinction between actual agency, regulatory notice and bounded remedial continuation.', 'Stone-Zsela':'Approved position separates liability attribution from alleged injury and ordinary remedy; evaluate against lower-count eligible alternatives.'},
source_map='The fresh-neutral validation and Meyer addendum supersede the original neutral shorthand concerning posture and ownership. They were supported by complete readings of the saved Ninth Circuit opinion and United States merits brief, including its September 2002 date and preservation discussion. Original party filings beyond that government brief were not read. The reconciled handoff separately verified the complete historical Meyer syllabus and opinion for comparator use. The record uses the independently validated summary-judgment posture, disputed ownership, absence of alleged direct participation and compensatory scope; it does not import a simplified comparator ownership description.'))

roe_holdings = '\n\n'.join([
holding('I. The agreed interview authorized entry within its own scope',
"An objectively understood, voluntarily arranged home interview permits the identified worker to enter for that interview when she arrives as agreed, absent withdrawal or an expressed limitation. The absence of a renewed express doorstep invitation does not revoke that antecedent permission, but the interview agreement does not authorize intimate bodily examination or photography.",
'Part I of the opinion of the Court; all nine Justices join this rule and explanation.',
"The Court accepts the mother's account that she did not expressly invite Strickland inside again at the doorway. Her acknowledged earlier agreement to an appointment at home, after learning the worker's identity and welfare purpose, nevertheless supplies affirmative authorization for the interview. The result rests on that agreement and its objective scope, not on silence as consent. Schneckloth v. Bustamonte supplies voluntary consent, and Ohio v. Robinette requires attention to the actual circumstances rather than an indispensable verbal formula. Johnson v. Jones and Behrens v. Pelletier permit assessment of the legal effect of the accepted account, not a credibility choice in the worker's favor. The mother's separate entry claim therefore fails, while the child's distinct search claim requires its own justification.",
'Schneckloth and Robinette are applied to voluntary, scope-limited authorization; Johnson and Behrens preserve the assumed-fact boundary of interlocutory legal review.'),
holding('II. This nonurgent intimate examination required consent or judicial authorization',
"A nonemergency investigative visual examination and photography of a child's genital and anal areas in these circumstances requires voluntary consent or appropriate judicial authorization supported by probable cause; genuine exigency is an independent exception. The claimant must establish the governmental search, and the official must substantiate consent or another invoked exception; cooperation with official directions does not conclusively establish voluntary consent.",
f'Part II of the opinion of the Court, joined by {seven_names}. Scalia and Thomas do not reach the constitutional merits; they neither join this rule nor vote that the search was constitutional. Seven direct joins control.',
"The Court examines the actual operation, as Ferguson v. City of Charleston requires, and the demonstrated need, as Chandler v. Miller requires. A protective purpose is substantial, but the challenged operation was intimate exposure, manipulation and photography by a worker without training in that photography, rather than an ordinary interview or superficial observation. The ten-day response classification, absence of claimed urgency or probable cause, and acknowledged medical-examination route supply no necessity for immediate intrusion without ordinary authorization. Griffin and Vernonia allow justified protective arrangements; they do not make a general protective mission sufficient for every investigative method. Statutory reporting duties or possible police contact do not categorically defeat special needs, and Ferguson's coordinated prosecution program is not a fact of this case. Good v. Dauphin County Social Services applies the Fourth Amendment in child-protection investigation; Darryl H. v. Coler likewise retains limits on scope and necessity under its different approach. Consent remains a distinct question. Under Schneckloth and Robinette, the mother's assistance in removing clothing and positioning the child, in response to official direction, must be considered with her questions about necessity and counsel, distress and lack of advance explanation of the eventual scope. These facts permit a finding of submission rather than permission; the Court requires no particular warning or verbal formula and assumes no threat to remove the child. On the supported plaintiff-favorable account of no voluntary consent, this search lacked the required justification. Actual consent remains for ordinary proceedings.",
'Ferguson and Chandler are applied to current merits, with their actual-operation and demonstrated-need limits. Griffin and Vernonia retain their justified protective settings; Good supplies child-investigation protection; Darryl H. is distinguished in scope and safeguards; Schneckloth and Robinette require actual voluntary consent.'),
holding('III. Pre-July 10, 1999 law supplied fair warning on the accepted account',
"Qualified immunity does not protect the assumed unconsented, highly intimate and nonurgent search because preconduct law made its lack of justification apparent under either plausible search framework. The legal inquiry uses supported plaintiff-favorable facts and law effective before July 10, 1999; materially different established facts remain subject to their own defenses, and later decisions supply no earlier notice.",
f'Part III of the opinion of the Court, joined by {seven_names}. Scalia and Thomas dissent from reversal of immunity. Seven direct joins control; no fractured-rationale synthesis is used.',
"Harlow v. Fitzgerald and Anderson v. Creighton require objective, particularized conduct-date notice. Wilson v. Layne distinguishes violation from personal immunity without demanding a factual twin; Elder v. Holloway requires all relevant preconduct law. Hope v. Pelzer explains how obvious application can give warning, but is not itself July 1999 notice. Before the search, Camara and New Jersey v. T.L.O. subjected civil officials and children's searches to the Fourth Amendment. Bell v. Wolfish required examination of scope, manner, justification and place. Vernonia and Chandler required real contextual justification, while Schneckloth and Robinette required voluntary consent rather than submission. Good specifically rejected a general child-protection exemption. The contrary authorities do not disappear: Darryl H. rejected a categorical warrant requirement and granted immunity despite substantial necessity and consent doubts. Yet it retained reasonableness limits, declined to treat maternal assistance as conclusive consent and identified medical examination for suspected sexual abuse. Landstrom involved a nurse's examination of complained-of soreness and a March 1987 notice date; Wildauer concerned an investigative home visit. Doe v. Louisiana granted Fourteenth Amendment immunity and expressly reserved the Fourth Amendment question. That reservation warrants care but does not affirmatively authorize this distinct nonmedical photography beyond the shared scope, necessity and consent limits. The Court's conclusion therefore does not depend on a settled warrant rule for every protective examination. It rests on the particular intrusion's obvious excess under either approach. Scalia and Thomas regard the immunity outcomes and unresolved local question as dispositive uncertainty; the Court instead finds the shared limits sufficiently concrete for the accepted lack of consent, probable cause and urgency. Ferguson, Wallis, Calabretta, Tenenbaum, Saucier and Hope create no July 1999 warning. Neither actual reading of precedent nor proof of actual reliance is required. No compulsory merits-first sequence is imposed.",
'Harlow, Anderson, Wilson and Elder retain objective, context-specific notice. Hope supplies the present method only. The listed preconduct scope and consent rules provide the warning; contrary child-protection cases are considered in their actual settings, not treated as a universal exemption.'),
holding('IV. The same entry and search do not create duplicate substantive-due-process claims',
"The mother's home-entry claim and the child's bodily-search claim are governed by the specific Fourth Amendment protection applicable to those acts, not a duplicate substantive-due-process damages theory. Failure to recover on a specific claim, including because of personal immunity, does not supply a separate substantive-due-process remedy for the same intrusion.",
'Part IV of the opinion of the Court; all nine Justices join this rule and explanation.',
"Graham v. Connor and the specific-provision rule preserved in County of Sacramento v. Lewis direct the identified intrusions to their express constitutional source. The record contains neither removal of the child nor a separate coercive displacement of a parental decision beyond the challenged examination. The mother's emotional injury does not itself establish that additional governmental act. This conclusion does not erase a parent's distinct family-liberty interest when a different supported act infringes it. It rejects these duplicative theories concerning the entry and examination, whose actual scope and justification are addressed by the Fourth Amendment.",
'Graham and Lewis are applied to the particular acts and claimants; distinct family-liberty claims based on different governmental conduct are not extinguished.'),
holding('V. The restored federal claim and state-law claims return in their actual posture',
"Texas official immunity must be assessed under its own law, independently of federal qualified immunity. With the child's federal search claim restored, any decision about supplemental jurisdiction must take account of that surviving claim; the unappealed dismissals of other defendants remain intact.",
f'Part V-A, the independence of Texas immunity, is joined by all nine. Part V-B, the restored-federal-claim remit and its supplemental-jurisdiction consequence, is joined by {seven_names}; Scalia and Thomas would instead leave the federal dismissal in place and preserve the independent state-law return.',
"The federal notice determination does not decide a Texas defense. The Fifth Circuit's state-law return must be conformed to the federal claim's restored posture, rather than implemented on an assumption that all federal claims have ended. Ordinary proceedings determine actual consent, personal responsibility, causation, injury, liability and remedy. Strickland must substantiate an invoked consent justification on the actual circumstances; the child must prove the actionable search and resulting compensable injury by a preponderance. If the proved facts materially differ from those assumed for the legal appeal, the court applies the governing defenses to those facts. A lawful discretionary refusal of supplemental jurisdiction remains governed by its actual predicates, and a jurisdictional dismissal is without prejudice. The department and other officials whose dismissals were not appealed are not restored by this mandate.",
'Johnson and Behrens preserve the difference between legal assumed-fact review and actual liability; the existing objective federal defense does not decide Texas official immunity.')])

roe_separate="Scalia, joined by Thomas, concurs in Parts I, IV and V-A and dissents from the reversal of child-search immunity and the consequential federal-claim remit. They affirm the interview-entry and duplicative-due-process rulings and preserve the independence of Texas immunity. They would affirm dismissal of all reviewed federal claims and return the state-law claims for evaluation of Texas immunity or a lawful decision declining supplemental jurisdiction, with a jurisdictional dismissal without prejudice. They do not decide the child's Fourth Amendment merits. In their view Anderson's particularized-notice requirement is not satisfied by the general gravity of this intrusion. Darryl H. rejected a categorical warrant-and-probable-cause requirement and granted immunity despite serious questions about necessity and consent; Landstrom likewise found insufficient clarity for an intimate examination. Doe v. Louisiana's local Fourth Amendment reservation left the application unsettled. Nonmedical photography is a material distinction, but the preconduct authorities had not made its personal-damages consequence sufficiently definite by July 10, 1999. A factual twin is unnecessary, all relevant other-circuit authority remains relevant, and child-protection workers have no blanket immunity. Nevertheless, the present Court's stronger merits interpretation cannot cure the earlier uncertainty. Ferguson, Wallis, Calabretta, Tenenbaum, Saucier and Hope cannot supply retrospective notice. Their position finds neither voluntary consent nor constitutional approval of the search."

cases.append(dict(key='Roe',number=40,case='Roe v. Texas Department of Protective and Regulatory Services',filename='Roe-v-Texas-Department-of-Protective-and-Regulatory-Services_merits_2003-06-02.md',date='2003-06-02',citation='Judgment below: 299 F.3d 395; Fifth Circuit No. 01-50711.',
result='Child-search immunity judgment reversed, 7–2; entry and duplicative-due-process dispositions affirmed, 9–0; remanded with state claims treated independently.',
event="Roe v. Texas Department of Protective and Regulatory Services. October Term 2002. Merits decision June 2, 2003, reviewing the Fifth Circuit's July 17, 2002 interlocutory immunity judgment, 299 F.3d 395, No. 01-50711. The questions concern a child-protection worker's nonurgent intimate examination and photography, conduct-date fair warning, the mother's scheduled-interview entry claim and overlapping substantive-due-process theories. The search occurred July 10, 1999. The Court accepts the supported plaintiff-favorable account for the legal appeal. The worker, Beverly Strickland, claimed neither probable cause nor exigency; consent to the intimate search remains disputed. The child's representatives seek federal damages relief; Strickland seeks immunity. The state-law claims had been remanded, and other defendants' dismissals were not appealed.",
judgment=f'| Component | Disposition and count | Supporting | Opposing |\n|---|---|---|---|\n| Child\'s Fourth Amendment damages claim: personal immunity | Reverse, 7–2 | {seven_names} | Scalia, Thomas |\n| Mother\'s scheduled-interview home-entry claim | Affirm rejection, 9–0 | {names} | None |\n| Duplicative substantive-due-process claims | Affirm rejection, 9–0 | {names} | None |\n| Independent Texas immunity inquiry | Preserve separate state-law consideration, 9–0 | {names} | None |\n| Consequential remand with a surviving child-search federal claim | Remand in restored-claim posture, 7–2 | {seven_names} | Scalia, Thomas favor remand after federal dismissal |\n\nThe child\'s Fourth Amendment claim returns for ordinary further proceedings under Parts II, III and V. The unappealed dismissals remain intact. The differing child-search merits reach is stated in the opinion topology and is not a separate damages judgment.',
topology='@@LEAD@@ delivered the opinion of the Court, in which @@LEAD_JOINERS@@ joined, and in which Scalia and Thomas joined as to Parts I, IV and V-A. Scalia filed an opinion concurring in part and dissenting in part, in which Thomas joined.\n\n| Writing | Author | Joined by | Relationship to judgment | Scope joined |\n|---|---|---|---|---|\n| Opinion of the Court | @@LEAD@@ | @@LEAD_JOINERS@@; Scalia and Thomas as to I, IV, V-A | Affirms entry and due-process dispositions; reverses child immunity; directs remand | Seven join all parts; all nine join I, IV and V-A |\n| Concurrence in part and dissent in part | Scalia | Thomas | Would affirm all reviewed federal dismissals and preserve independent state-law return | Joins I, IV and V-A; does not reach II; dissents from III and consequential V-B |',
holdings=roe_holdings,
precedent="- Schneckloth v. Bustamonte, 412 U.S. 218, and Ohio v. Robinette (November 18, 1996): applied to voluntary, circumstance-sensitive consent without a mandatory verbal formula.\n- Johnson v. Jones (June 12, 1995), and Behrens v. Pelletier (February 21, 1996): applied; interlocutory legal review uses supported assumed facts and cannot decide credibility or evidentiary sufficiency.\n- Ferguson v. City of Charleston (March 21, 2001): applied to current merits; actual operation requires its own justification, without a categorical mixed-purpose bar or retrospective notice.\n- Chandler v. Miller (April 15, 1997): applied; a demonstrated need must justify the intrusion.\n- Griffin v. Wisconsin, 483 U.S. 868, and Vernonia School District 47J v. Acton (June 26, 1995): their actual protective arrangements are distinguished from this unsubstantiated intimate method; the search and no-waiver principles remain.\n- Camara v. Municipal Court, 387 U.S. 523; New Jersey v. T.L.O., 469 U.S. 325; Bell v. Wolfish, 441 U.S. 520: their preconduct civil-search, child-search and scope/manner/justification rules inform the particular warning.\n- Harlow v. Fitzgerald, 457 U.S. 800, and Anderson v. Creighton, 483 U.S. 635: applied; objective, particularized legal notice remains the defense.\n- Elder v. Holloway (February 23, 1994), and Wilson v. Layne (May 24, 1999): applied; all relevant preconduct law and the violation/immunity distinction remain material without a factual-twin requirement.\n- Hope v. Pelzer (June 27, 2002): applies the obvious-application method with attention to contrary authority and hierarchy; it does not create 1999 notice.\n- Saucier v. Katz (June 18, 2001): preserves separate objective immunity analysis; it creates neither compulsory merits-first sequencing nor earlier notice.\n- Graham v. Connor, 490 U.S. 386, and County of Sacramento v. Lewis (May 26, 1998): applied to these acts under the specific Fourth Amendment source, without eliminating independent family-liberty claims.\n- Wallis v. Spencer (April 2, 2001): its independent-examination reservation supplies no resolution or conduct-date warning here.",
law="The bodily-search holding requires voluntary consent, probable cause with appropriate judicial authorization, or genuine exigency for the nonurgent intimate investigative operation addressed here. It does not impose one procedure on every protective inquiry or make police reporting alone decisive. The scheduled interview authorizes only its objective scope. On the accepted no-consent, no-probable-cause and no-urgency account, pre-July 10, 1999 law gave sufficient warning for the child-search claim to proceed. Actual liability remains subject to the proved facts and ordinary defenses. The same intrusions do not support duplicate substantive-due-process damages theories. Texas official immunity remains independent, and jurisdictional treatment must reflect the restored federal claim.",
separate=roe_separate,procedure='The case returns with the child-search federal claim restored and the entry and duplicative-due-process rejections intact. The courts proceed under the consent, responsibility, proof and remedy directions in Part V and assess the preserved state claims under their own law in that posture. The mandate does not revive unappealed defendant dismissals.',
sources='Roe v. Texas Department of Protective and Regulatory Services, 299 F.3d 395 (5th Cir. 2002), No. 01-50711. Good v. Dauphin County Social Services, 891 F.2d 1087 (3d Cir. 1989); Darryl H. v. Coler, 801 F.2d 893 (7th Cir. 1986); Landstrom v. Illinois Department of Children & Family Services, 892 F.2d 670 (7th Cir. 1990); Wildauer v. Frederick County, 993 F.2d 369 (4th Cir. 1993); Doe v. Louisiana, 2 F.3d 1412 (5th Cir. 1993). Actual consent, responsibility and injury remain factual issues; the interlocutory review does not resolve them by credibility choice.',
eligible=seven,full_joiners=seven,components=[dict(component='Child immunity',disposition='Reverse',supporting=seven,opposing=['Scalia','Thomas']),dict(component='Child merits',disposition='Adopt stated protection and plaintiff-favorable violation',supporting=seven,opposing=[],not_reached=['Scalia','Thomas']),dict(component='Entry',disposition='Affirm rejection',supporting=all_names,opposing=[]),dict(component='Duplicative substantive due process',disposition='Affirm rejection',supporting=all_names,opposing=[]),dict(component='State-law independence',disposition='Preserve',supporting=all_names,opposing=[]),dict(component='Restored-federal-claim remand',disposition='Remand in surviving federal claim posture',supporting=seven,opposing=['Scalia','Thomas'])],
compatibility="Stone's approved primary merits and notice positions match the six Associates' frozen R2/R3 rationale, producing seven direct joins. The actual record permits the shared-limit obvious-excess rationale; neither colleague dissent nor the mere existence of contrary decisions automatically triggers his conditional immunity fallback. All nine retain entry, particular-act due-process and independent Texas-immunity positions. Scalia and Thomas decline merits, not vote against a constitutional rule; they join V-A's independence only, not the restored-federal-claim mandate in V-B. Their compatible noncontrolling position is published jointly under Scalia, whose Anderson and Wilson work supplies concrete authorship fit; this separate writing does not count under balanced assignment. No Associate changes commitment, no factual consent finding or universal child-search rule is supplied, and no standing fallback is used.",
fit={'Souter':'Hope authorship supplies concrete fit for fair-warning specificity, hierarchy and contrary authority while separating current merits from 1999 notice.', 'Ginsburg':'Elder and Behrens authorship supplies fit for all-relevant-law review and the assumed-fact/claim-specific boundary.', 'O\'Connor':'Robinette authorship supplies fit for voluntary consent and interview-versus-examination scope.', 'Kennedy':'Ferguson authorship supplies fit for actual-operation special-needs review without turning later law into preconduct warning.', 'Stone-Zsela':'Approved position coordinates distinct search, notice, attribution and remedy inquiries; compare the eligible pool alternatives.'},
source_map='The frozen neutral packet cites the complete official Fifth Circuit opinion and all footnotes, with a reported-text cross-check. The reconciled commitment incorporates the modeling stage\'s additional full preconduct-law research and carefully preserves Darryl H., Landstrom, Wildauer and Doe as contrary authority. The entering-law slice supplies the actual current holdings of Saucier, Hope, Ferguson, Wallis, Robinette, Vernonia, Chandler, Johnson, Behrens, Elder and Wilson. The June 2, 2003 review/date premise is adopted; no separate argument or submission date is supplied. The legal-notice cutoff is July 10, 1999, distinct from the adjudication research cutoff. No later decision supplies earlier notice.'))

audit_names={'Norton':'Norton — existing holdings control the facial questions','Newman':'Newman — protected entitlement does not predetermine process','Meyer':'Meyer — full same-matter comparator confirms the retained ordinary-law remit','Roe':'Roe — preserve the merits/notice division and the different claims'}
metadata=[]
for c in cases:
    approved = section(stone, f"## {c['number']}. ", '\n## ')
    frozen = section(reconciled, f"## {c['number']}. ", '\n## ')
    audit = section(reconciled, '### '+audit_names[c['key']], '\n### ')
    if c['key']=='Roe':
        audit=audit.split('\n## Final validation')[0].strip()
    public_blocks = [
        ('Event',c['event']),
        ('Participation',f'Chief Justice Stone-Zsela and Justices {eight_names} participated at submission and decision. All nine participate.'),
        ('Public Action',c['result']),
        ('Judgment & Remedy',c['judgment']),
        ('Opinion Topology',c['topology']),
        ('Holdings',c['holdings']),
        ('Precedent Treatment',c['precedent']),
        ('Law After Decision',c['law']),
        ('Separate Writings',c['separate']),
        ('Procedure After Action',c['procedure']),
        ('Source Notes',c['sources'])]
    public='\n\n'.join(f'## {heading}\n\n{body}'.rstrip() for heading,body in public_blocks)
    internal=f"""**Case and dockets:** {c['case']}. {c['citation']}
**Event and date:** Merits decision; {c['date']}; October Term 2002, chunk 3.
**Result:** {c['result']}
**Version / lineage:** Original decision.

## Decision kernel

{c['event']}

**Participation and channel:** All nine Justices participate at merits submission and decision: {names}. Quorum is satisfied; five votes form a participating majority. The authorized proper-review premise supplies the merits channel; no unidentified grant or filing is invented. {'The argument date is December 3, 2002.' if c['key']=='Meyer' else 'No separate argument or submission date is supplied; none is inferred.'}

**Research cutoff:** {c['date']}. Only earlier-effective public law enters. {'The independent personal-immunity notice cutoff is July 10, 1999.' if c['key']=='Roe' else ''}

**Entering law:** `terms/OT2002/entering-law/OT_2002CHUNK3_C.md`, together with the frozen neutral source limits and the applicable fresh Meyer validation. The reading slice is derivative; the authority it identifies remains controlling. Undecided matters add no law. Norton's ACLA dependency is effective December 10, 2002; June 26, 2003 matters do not enter Roe.

**Form fixed before assignment:** One signed lead opinion after plenary merits review. The single opinion follows the actual common propositions and the component joins below; no count or potential author determines its form, scope or division. This is a counted lead opinion under Engine §8. Separate writings reflect the stated substantive differences only.

**Assignment:** @@ASSIGNMENT@@

## Final judgment and remedy

{c['judgment']}

## Final opinion table

{c['topology']}

{('''| Writing | Author | Joined by | Scope |
|---|---|---|---|
| Opinion of the Court | @@LEAD@@ | @@LEAD_JOINERS@@ | Entire opinion |''') if c['key'] in ['Norton','Meyer'] else ''}

## Controlling holdings

{c['holdings']}

## Precedent and current law

{c['precedent']}

{c['law']}

## Stone approval and final compatibility

{c['compatibility']}

### Approved supplement, copied without substantive alteration

{approved}

## Continuity and remaining work

{c['procedure']}

{c['separate'] if c['separate'] else 'No separate writing or additional noncontrolling position issues in this matter.'}

No roster, circuit allotment or institutional-practice change results. The ordinary post-decision proceedings specified above remain; no unsupported later event is presumed. The controlling propositions and identified noncontrolling writings supply subsequent continuity at their actual scope.

## Sources and validation status

{c['source_map']}

**Frozen inputs:** `terms/OT2002/freeze/OT_2002CHUNK3_C_NEUTRAL.md`; `terms/OT2002/freeze/OT_2002CHUNK3_C_RECONCILED.md`; `terms/OT2002/runtime/OT_2002CHUNK3_C_STONE.md`. Meyer additionally uses the Meyer sections of `terms/OT2002/freeze/OT_2002CHUNK3_FRESH_NEUTRAL_VALIDATION.md` and `terms/OT2002/freeze/OT_2002CHUNK3_FRESH_NEUTRAL_ADDENDUM.md`. The preflight exposure receipt remains internal; fresh validation and modeling cured the affected premise before reconciliation. This assembly uses the approved material including language labeled proposed; that wording does not make another Justice adopt it.

**Validation:** @@VALIDATION@@

## Adaptive audit annex: retained Associate commitments

The following case section is copied from the frozen reconciled handoff. Its assignment references describe its earlier stage; the final table above controls completed assembly. No frozen Associate commitment is changed.

{frozen}

## Adaptive audit annex: historical comparison

{audit}

**Departure status:** {'The child-immunity result differs from the historical lower-court result, for the Justice-specific notice grounds preserved above; there is no historical Supreme Court merits lineup to displace.' if c['key']=='Roe' else 'No same-matter historical Supreme Court Justice departure is established. Meyer matches the historical ordinary-agency result; the other group matters have lower-court historical anchors only.'}

## Public Projection

{public}
"""
    (OUT/c['filename']).write_text(internal,encoding='utf-8')
    metadata.append(dict(case=c['case'],filename=c['filename'],date=c['date'],fixedopinionform='one signed opinion of the Court after plenary merits review; form fixed before assignment',eligible_full_rationale_authors=c['eligible'],full_joiners=c['full_joiners'],majorityjudgment=c['components'][0]['supporting'],componentvote_arrays=c['components'],plausibleauthorfit_alternatives=c['fit'],assignment_authority='Chief Justice Stone-Zsela, in every judgment majority',separate_writing=('Stone-Zsela, concurrence in part and in judgment' if c['key']=='Newman' else 'Scalia, joined Thomas, concurrence in part and dissent in part' if c['key']=='Roe' else None),compatibility=c['compatibility']))

(BASE/'runtime/OT_2002CHUNK3_C_ASSEMBLY.json').write_text(json.dumps(metadata,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

expected=[x[0] for x in public_blocks]
for c in cases:
    text=(OUT/c['filename']).read_text(encoding='utf-8')
    internal,public=text.split('\n## Public Projection\n',1)
    got=re.findall(r'^## (.+)$',public,re.M)
    assert got==expected,(c['case'],got)
    public_h=section(public,'## Holdings\n','\n## Precedent Treatment').removeprefix('## Holdings\n').strip()
    internal_h=section(internal,'## Controlling holdings\n','\n## Precedent and current law').removeprefix('## Controlling holdings\n').strip()
    assert public_h==internal_h
    assert '@@LEAD@@' in text and '@@LEAD_JOINERS@@' in text and '@@ASSIGNMENT@@' in text and '@@VALIDATION@@' in text
    excluded=('one'+'drive','git'+'hub')
    assert not any(x in text.lower() for x in excluded)
    assert not re.search(r'[A-Z]:[\\/]|file://',text)
    print(c['filename'], 'eleven blocks; holdings identity; placeholders; path/service check: PASS')

